'use strict';
// ===== VOID SECTOR — Этап 4: сюжетный слой (story.js) =====
// Загружается ПОСЛЕДНИМ. Подписывается на шину событий (events.js: on/emit),
// показывает переговоры в панели «ЭФИР» внизу экрана, стенограмму в ангаре,
// правит текст меню и финального экрана. Игру не останавливает и ничего
// в существующих файлах не меняет.
//
// Персонажи: Спектр (пилот «Вектора»), майор Воронова, Лея (оператор),
// доктор Марков, Неизвестный (командор «Персея» Артём Соколов — Архонт Бездны).

// ---------------------------------------------------------------------------
// 1. Персонажи
// ---------------------------------------------------------------------------
const storyCharacters={
 spectre:{name:'СПЕКТР',color:'#98f8ed',pitch:.9,rate:1},
 voronova:{name:'МАЙОР ВОРОНОВА',color:'#ffb27a',pitch:.8,rate:1},
 leya:{name:'ЛЕЯ',color:'#9fd7ff',pitch:1.15,rate:1.05},
 markov:{name:'ДОКТОР МАРКОВ',color:'#d5c7ff',pitch:.95,rate:.95},
 unknown:{name:'НЕИЗВЕСТНЫЙ',revealedName:'СОКОЛОВ',color:'#ff6b8a',pitch:.55,rate:.85}
};
function storyName(who){const c=storyCharacters[who]||storyCharacters.leya;return who==='unknown'&&storyState.unknownRevealed?c.revealedName:c.name}

