  contact:[L('leya','Корсары. Веер пулемётного огня — не стой на одной линии.')],
  change:[L('leya','Поле уплотняется. Опасные камни можно расстрелять или обойти.'),L('spectre','Расстреляю.'),L('leya','Ну конечно.')],
  climax:[L('voronova','Корсары перекрывают выход. Проламывай.'),L('leya','Спектр, справа ещё три сигнатуры.'),L('spectre','Вижу.'),L('leya','Нет. Эти три — только сопровождение.')],
